-- OutreachOS 2GIS top-up: сид рубрикатора v1 (дизайн-док §6) + включение в measure-режиме.
-- Применено на проде 2026-08-11 (вручную, по подтверждению владельца).
--
-- Рубрикатор собран по ТОЧНЫМ названиям из 2gis_dataset.facet_subcategories (снапшот
-- 2026-07-26). Режимы: includedSubcategories → 'some', excludedSubcategories → 'allExcept',
-- без списков → 'all' (см. toTwoGisRubricGroups в app/src/lib/twoGis/rubricGroups.ts).
--
-- measure_only=true: завтрашний прогон (05:15 МСК) измерит воронку добора
-- (gis_pulled/after_dedup/valid_contacts/llm_kept в outreachos_pipeline_runs)
-- БЕЗ заливки в Instantly и БЕЗ записи seen. Live-включение — отдельным решением
-- после разбора замеров.

UPDATE public.outreachos_pipeline_config
SET gis_topup_rubric_groups = $json$[
  {"category":"Транспорт / Грузоперевозки","excludedSubcategories":["Пункты выдачи интернет-заказов","Такси","Междугородные / Международные пассажирские перевозки","Пассажирские транспортные предприятия","Проездные билеты / Транспортные карты","Авиабилеты","Железнодорожные билеты","Пригородные кассы","Автовокзалы","Автобусные билеты","Заказ трансфера","Прокат автотранспорта","Продажа легковых автомобилей","Оформление купли-продажи автомобилей","Автомобильные номера","Подбор автомобиля перед покупкой","Автоэкспертиза","Мототехника","Гаражные кооперативы","Коллективные автостоянки","Помощь в оформлении кредита"]},
  {"category":"Юридические / финансовые / бизнес-услуги","includedSubcategories":["Юридические услуги","Ведение дел в судах","Услуги адвоката","Бухгалтерские услуги","Аудиторские услуги","Регистрация / ликвидация предприятий","Управленческий консалтинг","Финансовый консалтинг","Оценка собственности","Лизинговые услуги","Лицензирование","Патентные услуги","Защита авторских прав","Организация и проведение тендеров / аукционов","Экспертиза промышленной безопасности","Таможенное оформление","Сертификация","Пожарная безопасность","Охрана труда","Экологическая оценка","Арбитражный управляющий","Саморегулируемые организации"]},
  {"category":"Строительство / Недвижимость / Ремонт","excludedSubcategories":["Агентства недвижимости","Новостройки","Помощь в оформлении ипотеки","Оформление недвижимости","Продажа участков / малоэтажных домов","Строительство дач / коттеджей","Строительство бань / саун","Дизайн интерьеров","Ландшафтный дизайн","Коворкинг","Торговые центры"]},
  {"category":"Строительные / отделочные материалы"},
  {"category":"Оборудование / Инструмент"},
  {"category":"Металлы / Топливо / Химия"},
  {"category":"Интернет / Связь / Информационные технологии","includedSubcategories":["Разработка / продвижение сайтов","Автоматизация бизнес-процессов","Программное обеспечение","IP-телефония","Автоматизация производства","Системное администрирование","Разработка программного обеспечения","Информационная безопасность","Хостинг","Разработка мобильных приложений","IT-компании"]},
  {"category":"Охрана / Безопасность"}
]$json$::jsonb,
    gis_topup_enabled = true,
    gis_topup_measure_only = true,
    updated_at = now()
WHERE id = 1;
